// Minimal sketch
interface AuthStrategy { authenticate(req): boolean; identity(req): Identity }
class ApiKeyAuth implements AuthStrategy { authenticate(req) { ... } identity(req) { ... } }
class JwtAuth implements AuthStrategy { authenticate(req) { ... } identity(req) { ... } }
class HmacAuth implements AuthStrategy { authenticate(req) { ... } identity(req) { ... } }

class AuthRegistry {
  constructor() { this.factories = new Map() }
  register(name, factory) { this.factories.set(name, factory) }
  getFor(req) {
    const scheme = parseScheme(req.headers)
    const factory = this.factories.get(scheme)
    return factory ? factory() : null
  }
}
